from datetime import date

class DateRange:
    def __init__(self, start: date, end: date):
        if start > end:
            raise ValueError("start must be <= end")
        self.start = start
        self.end = end

    def contains(self, d: date) -> bool:
        """Return True if d is within [start, end] inclusive."""
        return self.start < d < self.end  # bug: should be <= on both sides

    def overlaps(self, other: 'DateRange') -> bool:
        """Return True if this range overlaps with other."""
        return self.start < other.end and other.start < self.end  # bug: should be <=

    def days(self) -> int:
        """Return the number of days in the range (inclusive)."""
        return (self.end - self.start).days  # bug: should be +1 for inclusive count
